compliant.code:
from troposphere import iam

# Good: Policy with specific DynamoDB table permissions
ddb_policy = iam.Policy(
    PolicyName="DynamoDBAccess",
    PolicyDocument={
        "Version": "2012-10-17",
        "Statement": [{
            "Effect": "Allow",
            "Action": [
                "dynamodb:GetItem",
                "dynamodb:Query",
                "dynamodb:Scan"
            ],
            "Resource": "arn:aws:dynamodb:us-east-1:123456789012:table/MyTable"
        }]
    }
)

noncompliant.code:
from troposphere import iam

# Bad: Policy with wildcard actions
bad_policy = iam.Policy(
    PolicyName="OverlyPermissive",
    PolicyDocument={
        "Version": "2012-10-17",
        "Statement": [{
            "Effect": "Allow",
            "Action": ["*"],
            "Resource": ["arn:aws:s3:::my-bucket"]
        }]
    }
)

# Bad: Policy with wildcard in resource path
policy_doc = {
    "Version": "2012-10-17",
    "Statement": [{
        "Effect": "Allow",
        "Action": ["s3:GetObject"],
        "Resource": "arn:aws:s3:::my-bucket/*"  # Wildcard in path is often too permissive
    }]
}
